css:
.word {
  color: white;
  display: flex;
  flex-direction: row;
  font-size: 1em;
}
.letter {
  animation: letter 1s ease-in-out infinite alternate;
  animation-delay: calc(-1 * var(--i) * 0.2s);
}
@keyframes letter {
  0% {
    font-weight: 700;
    font-size: 3em;
  }
  100% {
    font-weight: 100;
    font-size: 2em;
  }
}
